route {
	...
	async(cgrates\_auth("$fU", "$rU"), auth\_reply);
}

route \[auth\_reply\]
{
	if ($rc < 0) {
		xlog("Call not authorized: code=$cgr\_ret!\\n");
		send\_reply(403, "Forbidden");
		exit;
	}
	...
}

